double relu(double x) {
    if (x &gt; 0.0) {
        return x;
    } else {
        return 0.0;
    }
}

// Task 2: derivata della ReLU (0 in x = 0)
double relu_derivative(double x) {
    if (x &gt; 0.0) {
        return 1.0;
    } else {
        return 0.0;
    }
}




main.cpp

// Task 3: sigmoide e sua derivata
double sigmoid(double x) {
    return 1.0 / (1.0 + std::exp(-x));
}

double sigmoid_derivative(double x) {
    double s = sigmoid(x);   // una sola volta
    return s * (1.0 - s);
}

// Task 5: tanh e sua derivata (nome tanh_act)
double tanh_act(double x) {
    return std::tanh(x);
}

double tanh_derivative(double x) {
    double t = std::tanh(x); // una sola volta
    return 1.0 - t * t;
}

Soluzione del Laboratorio 03, Task 4–6: la tabella


main.cpp

// Task 6: derivate numeriche (differenze centrali)
double sigmoid_numerical_derivative(double x, double h) {
    return (sigmoid(x + h) - sigmoid(x - h)) / (2.0 * h);
}

double tanh_numerical_derivative(double x, double h) {
    return (tanh_act(x + h) - tanh_act(x - h)) / (2.0 * h);
}

int main() {
    // Task 4 e 5: tabella da -5 a 5 a passi di 1, contatore int
    std::cout &lt;&lt; "x\trelu\trelu'\tsigmoid\tsigmoid'\ttanh\ttanh'" &lt;&lt; std::endl;
    for (int i = -5; i &lt;= 5; ++i) {
        double x = i;
        std::cout &lt;&lt; x &lt;&lt; "\t" &lt;&lt; relu(x) &lt;&lt; "\t" &lt;&lt; relu_derivative(x) &lt;&lt; "\t"
                  &lt;&lt; sigmoid(x) &lt;&lt; "\t" &lt;&lt; sigmoid_derivative(x) &lt;&lt; "\t"
                  &lt;&lt; tanh_act(x) &lt;&lt; "\t" &lt;&lt; tanh_derivative(x) &lt;&lt; std::endl;
    }

