// Task 5: righe, colonne e dati di una matrice, tenuti insieme
struct CMatrix {
    int rows;
    int cols;
    double* data;   // rows*cols double, in ordine row-major
};

CMatrix cmat_alloc(int rows, int cols) {
    CMatrix m;
    m.rows = rows;
    m.cols = cols;
    m.data = new double[rows * cols];
    return m;
}

void cmat_free(CMatrix& m) {
    delete[] m.data;
    m.data = nullptr;   // delete[] su nullptr non fa nulla
    m.rows = 0;
    m.cols = 0;
}


