Il task. Task 5: cmat_get e cmat_set; Task 6: layer_forward.


main.cpp

// elemento (i, j): la riga i occupa cols celle consecutive
double cmat_get(const CMatrix& m, int i, int j) {
    return m.data[i * m.cols + j];
}

void cmat_set(CMatrix& m, int i, int j, double val) {
    m.data[i * m.cols + j] = val;
}

// Task 6: z[j] = somma_i W(j, i) * x[i] + b[j], prodotto matrice-vettore
void layer_forward(const CMatrix& W, const double* x, const double* b, double* z) {
    for (int j = 0; j &lt; W.rows; ++j) {
        double acc = 0.0;
        for (int i = 0; i &lt; W.cols; ++i) {
            acc += cmat_get(W, j, i) * x[i];
        }
        z[j] = acc + b[j];
    }
}

