#include &lt;iostream&gt;

int main() {
    std::vector&lt;int&gt; v = {99, 10, 50, 5};

1    std::sort(v.begin(), v.end());
    // Ora v è {5, 10, 50, 99}

    auto max_it = std::max_element(v.begin(), v.end());
    std::cout &lt;&lt; "Il numero più grande è: " &lt;&lt; *max_it &lt;&lt; "\n";
