    double** m = new double*[righe];                     // un puntatore per riga
    for (int i = 0; i &lt; righe; ++i)
1        m[i] = dati + i * colonne;
    for (int i = 0; i &lt; righe; ++i)
        for (int j = 0; j &lt; colonne; ++j)
2            m[i][j] = i * colonne + j;
    std::cout &lt;&lt; m[2][3] &lt;&lt; " " &lt;&lt; dati[2 * colonne + 3] &lt;&lt; "\n";   // stampa 11 11
3    delete[] m;
    delete[] dati;
