    std::cout &lt;&lt; x &lt;&lt; "\n";    // 3.5
2    std::cout &lt;&lt; p &lt;&lt; "\n";    // un indirizzo
    std::cout &lt;&lt; *p &lt;&lt; "\n";   // 3.5

3    *p = 7.0;
