#include "matrix.hpp"
#include &lt;stdexcept&gt;   // invalid_argument, out_of_range

Matrix::Matrix(int r, int c) : rows(r), cols(c) {
    if (r &lt;= 0 || c &lt;= 0) {
        throw std::invalid_argument(
            "Matrix: dimensioni non positive");
    }
    data = new double[rows * cols];
    for (int i = 0; i &lt; rows * cols; i++) {
        data[i] = 0.0;
    }
}

Matrix::~Matrix() {
    delete[] data;
}


Copiate il codice all’inizio di matrix.cpp.

Il costruttore fa il lavoro di cmat_alloc e azzera gli elementi. Con dimensioni non positive lancia un’eccezione (Lezione 10) e l’oggetto non viene creato.
Il distruttore fa il lavoro di cmat_free ed è chiamato automaticamente.

