// un blocco nuovo, con gli stessi valori di altra
Matrix::Matrix(const Matrix& altra)
    : rows(altra.rows), cols(altra.cols),
      data(new double[altra.rows * altra.cols]) {
    for (int i = 0; i &lt; rows * cols; i++) {
        data[i] = altra.data[i];
