Un esempio con Eigen


#include &lt;iostream&gt;
#include &lt;Eigen/Dense&gt;

int main() {
    Eigen::MatrixXd W = Eigen::MatrixXd::Zero(2, 3);
    W(0, 0) = 1.0;
    W(1, 2) = 2.0;

    Eigen::MatrixXd x = Eigen::MatrixXd::Zero(3, 1);
    x(0, 0) = 3.0;
    x(2, 0) = 4.0;

    Eigen::MatrixXd b = Eigen::MatrixXd::Zero(2, 1);
    b(1, 0) = 0.5;

    Eigen::MatrixXd z = W * x + b;
    std::cout &lt;&lt; "z: " &lt;&lt; z.rows() &lt;&lt; " x " &lt;&lt; z.cols()
              &lt;&lt; std::endl;
    std::cout &lt;&lt; z &lt;&lt; std::endl;
    return 0;
}

Output:
z: 2 x 1
  3
8.5

W è \(2 \times 3\), x è \(3 \times 1\) (un vettore colonna): z è \(2 \times 1\).
\(z_0 = 1 \cdot 3 = 3\), \(z_1 = 2 \cdot 4 + 0{,}5 = 8{,}5\).
Se le colonne di W non sono quante le righe di x, Eigen interrompe il programma: invalid matrix product.

