#include "Vettore2D.hpp"
#include &lt;cmath&gt;

Vettore2D Vettore2D::operator+(const Vettore2D& altro) const {
    return Vettore2D(x_ + altro.x_, y_ + altro.y_);
}

Vettore2D Vettore2D::operator-(const Vettore2D& altro) const {
    return Vettore2D(x_ - altro.x_, y_ - altro.y_);
}

