#include &lt;iostream&gt;
#include &lt;string&gt;
#include "Funzione2D.hpp"

int discesa(const Funzione2D& f, Vettore2D& x,
            double eta, int max_passi) {
    for (int n = 1; n &lt;= max_passi; ++n) {
1        x = x - f.gradiente(x) * eta;
        double g = f.gradiente(x).norma();
        if (g &lt; 1e-6) return n;
        if (g &gt; 1e10) return -1;
    }
    return max_passi;
}


1

gradiente è virtuale: si esegue il metodo della classe vera dell’oggetto, Paraboloide o Rosenbrock.



Un riferimento alla classe base funziona come un puntatore: f è un const Funzione2D&, e f.gradiente(x) esegue il metodo della classe vera.
