#include &lt;cmath&gt;
#include &lt;iostream&gt;

class Attivazioni {
public:
    static double relu(double z) { return z &gt; 0.0 ? z : 0.0; }
    static double sigmoide(double z) {
        return 1.0 / (1.0 + std::exp(-z));
    }
};

int main() {
    std::cout &lt;&lt; Attivazioni::relu(-5.0) &lt;&lt; " "
              &lt;&lt; Attivazioni::sigmoide(0.0) &lt;&lt; "\n";
    return 0;
}


