#include &lt;fstream&gt;
#include &lt;iostream&gt;
#include &lt;stdexcept&gt;
#include &lt;string&gt;
#include &lt;Eigen/Dense&gt;

// la prima cifra di mnist_test.csv: 28 x 28, fra 0 e 1
Eigen::MatrixXd prima_immagine(const std::string& nome) {
    std::ifstream f(nome);
    if (!f) throw std::runtime_error("non trovo " + nome);
    std::string intestazione;
    std::getline(f, intestazione);
    int etichetta;
    char virgola;
    f &gt;&gt; etichetta;
    Eigen::MatrixXd x(28, 28);
    for (int i = 0; i &lt; 28; ++i)
        for (int j = 0; j &lt; 28; ++j) {
            f &gt;&gt; virgola &gt;&gt; x(i, j);
            x(i, j) /= 255.0;
        }
    return x;
}


