Il downcasting con static_cast




downcasting.cpp

#include &lt;iostream&gt;
#include "layers.hpp"

int main() {
    Layer* p = new DenseLayer(128, 784);
    Layer* q = new SigmoidLayer();
    DenseLayer* d = static_cast&lt;DenseLayer*&gt;(p);
    std::cout &lt;&lt; d-&gt;numero_pesi() &lt;&lt; "\n";
