Soluzione dell’esercizio




esercizio_accumulatore.cpp

#include &lt;iostream&gt;
#include &lt;string&gt;

template &lt;typename T&gt;
class Accumulatore {
private:
    T somma_;
    int n_;
public:
    Accumulatore() : somma_(T{}), n_(0) {}
    void aggiungi(const T& v) {
        somma_ += v;
        n_++;
    }
    T totale() const { return somma_; }
    int quanti() const { return n_; }
    double media() const {
        if (n_ == 0) return 0.0;
        return static_cast&lt;double&gt;(somma_) / n_;
    }
};


somma_(T{}) parte da 0 per int e double, dalla stringa vuota per std::string: con somma_(0) la classe funzionerebbe solo con i numeri.
media converte la somma in double prima della divisione: con int, 12 / 3 darebbe la divisione intera.

