esercizio_albero.cpp

#include &lt;iostream&gt;
#include &lt;memory&gt;
#include &lt;random&gt;
#include &lt;utility&gt;

struct Nodo {
    double dato;
    Nodo* su = nullptr;                      // il genitore: non lo possiede
    std::unique_ptr&lt;Nodo&gt; sinistra, destra;  // i figli: li possiede
    Nodo(double d) : dato(d) {}
};

int profondita(const Nodo* p) {
    int h = 0;
    while (p-&gt;su != nullptr) {
        p = p-&gt;su;
        h++;
    }
    return h;
}

profondita risale con su fino alla radice, l’unico nodo con su uguale a nullptr.

Soluzione: inserisci


esercizio_albero.cpp

void inserisci(std::unique_ptr&lt;Nodo&gt; nuovo, Nodo* vecchio) {
    if (nuovo-&gt;dato &lt;= vecchio-&gt;dato) {
        if (vecchio-&gt;sinistra == nullptr) {
            nuovo-&gt;su = vecchio;
            vecchio-&gt;sinistra = std::move(nuovo);
        } else {
            inserisci(std::move(nuovo), vecchio-&gt;sinistra.get());
        }
    } else {
        if (vecchio-&gt;destra == nullptr) {
            nuovo-&gt;su = vecchio;
            vecchio-&gt;destra = std::move(nuovo);
        } else {
            inserisci(std::move(nuovo), vecchio-&gt;destra.get());
        }
    }
}


Righe 24 e 25: nuovo-&gt;su = vecchio va scritto prima di std::move(nuovo), perché dopo il nodo appartiene a vecchio-&gt;sinistra e nuovo vale nullptr.
Riga 27: il nodo nuovo passa con std::move alla chiamata successiva, finché non trova il suo posto; get() dà l’indirizzo del figlio senza cederlo.

Soluzione: il main


esercizio_albero.cpp

int main() {
    std::mt19937 motore(12345);
    std::uniform_real_distribution&lt;double&gt; uniforme(0.0, 1.0);
    const int R = 100;                                // alberi per ogni N
    for (int N = 100; N &lt;= 10000; N *= 10) {
        double media = 0.0, massima = 0.0;
        for (int r = 0; r &lt; R; r++) {
            std::unique_ptr&lt;Nodo&gt; radice = std::make_unique&lt;Nodo&gt;(uniforme(motore));
            long somma = 0;                           // la radice ha profondita' 0
            int hmax = 0;
            for (int i = 1; i &lt; N; i++) {
                std::unique_ptr&lt;Nodo&gt; nuovo = std::make_unique&lt;Nodo&gt;(uniforme(motore));
                Nodo* p = nuovo.get();                // l'indirizzo, prima di cederlo
                inserisci(std::move(nuovo), radice.get());
                int h = profondita(p);
                somma += h;
                if (h &gt; hmax) hmax = h;
            }
            media += static_cast&lt;double&gt;(somma) / N;
            massima += hmax;
        }                                             // qui radice distrugge l'albero
        std::cout &lt;&lt; N &lt;&lt; "  " &lt;&lt; media / R &lt;&lt; "  " &lt;&lt; massima / R &lt;&lt; "\n";
    }
    return 0;
}

