DenseLayer::DenseLayer(int Nn, int Ni, InitType type,
                       DistroType distro) {
    double s = 0.0;
    switch (type) {
        case InitType::HE:
            s = (distro == DistroType::UNIFORM)
                    ? std::sqrt(6.0 / Ni) : std::sqrt(2.0 / Ni);
            break;
        case InitType::XAVIER:
            s = (distro == DistroType::UNIFORM)
                    ? std::sqrt(6.0 / (Ni + Nn)) : std::sqrt(2.0 / (Ni + Nn));
            break;
    }
