#include "activation_layers.hpp"

// sigma(z) = 1 / (1 + exp(-z)), elemento per elemento
Eigen::MatrixXd SigmoidLayer::forward(const Eigen::MatrixXd& input) {
    Eigen::MatrixXd output = 1.0 / (1.0 + (-input.array()).exp());
    return output;
}

// Task 4, da scrivere: tanh(z), elemento per elemento
Eigen::MatrixXd TanhLayer::forward(const Eigen::MatrixXd& input) {
    Eigen::MatrixXd output = input.array().tanh();
    return output;
}

Soluzione del Laboratorio 08, Task 6
Il task. Facoltativo: la funzione chi_quadro, come chiSquare del Listato 7.11 del libro, che restituisce \(\Phi = \sum_{\alpha} (Y_\alpha - n\,p_\alpha)^2 / (n\,p_\alpha)\):
double chi_quadro(const int* oss, const double* att, int K) {
    double S = 0.0;
    for (int k = 0; k &lt; K; k++)
        S += (oss[k] - att[k]) * (oss[k] - att[k]) / att[k];
    return S;
}
