Task 5 (segue): il forward della rete
    // l'uscita di ogni layer e' l'ingresso del successivo, senza copie
    Matrix&lt;ntype&gt;& forward(const Matrix&lt;ntype&gt;& input) override {
        if (layers.size() == 0)
            throw std::runtime_error("[Sequential] la rete non ha layer");
        const Matrix&lt;ntype&gt;* ingresso = &input;   // l'ingresso del prossimo layer
        Matrix&lt;ntype&gt;* uscita = nullptr;          // l'uscita dell'ultimo layer
        for (Layer&lt;ntype&gt;* l : layers) {
            uscita = &l-&gt;forward(*ingresso);
            // Task 5, da completare: l'uscita di l diventa l'ingresso del prossimo layer
        }
        return *uscita;
    }
ingresso e uscita sono puntatori a matrici; ingresso è un puntatore a una matrice costante (Lezione 06), perché la matrice d’ingresso si legge e non si modifica. l-&gt;forward(*ingresso) restituisce un reference all’outputs di l, e con & se ne prende l’indirizzo: da un layer al successivo passa un indirizzo, nessuna matrice viene copiata.
Da scrivere: al posto del commento, una riga che fa puntare ingresso dove punta uscita.

Task 6: float e double
Scopo: la stessa rete in float e in double, e la differenza fra le uscite. Le due reti devono differire solo nel tipo degli elementi.
void confronto_precisione() {
    rng.seed(42);
    Sequential&lt;float&gt; rete32;
    rete32.add(new DenseLayer&lt;float&gt;(128, 784));
    rete32.add(new SigmoidLayer&lt;float&gt;());
    rete32.add(new DenseLayer&lt;float&gt;(10, 128));
    rete32.add(new TanhLayer&lt;float&gt;());

    rng.seed(42);                        // di nuovo: gli stessi pesi
    Sequential&lt;double&gt; rete64;
    rete64.add(new DenseLayer&lt;double&gt;(128, 784));
    rete64.add(new SigmoidLayer&lt;double&gt;());
    rete64.add(new DenseLayer&lt;double&gt;(10, 128));
    rete64.add(new TanhLayer&lt;double&gt;());

    Matrix&lt;float&gt; x32(784, 1);
    for (int i = 0; i &lt; 784; i++) x32(i) = rng.ranf();
    Matrix&lt;double&gt; x64 = x32.cast&lt;double&gt;();   // lo stesso ingresso, in double

    Matrix&lt;float&gt;& y32 = rete32.forward(x32);
    Matrix&lt;double&gt;& y64 = rete64.forward(x64);
    double scarto = (y32.cast&lt;double&gt;() - y64).cwiseAbs().maxCoeff();
    std::cout &lt;&lt; "scarto massimo float/double: " &lt;&lt; scarto &lt;&lt; std::endl;
}

